"""Lossless stdlib-only file compressor. Usage: compress.py [--decompress] IN OUT."""
import bz2
import pathlib
import sys


def compress(data):
    return b'BC1' + bz2.compress(data, compresslevel=9)


def decompress(data):
    if not data.startswith(b'BC1'):
        raise ValueError('Unknown compressed format')
    return bz2.decompress(data[3:])


def main():
    args = sys.argv[1:]
    decode = bool(args and args[0] == '--decompress')
    if decode:
        args = args[1:]
    if len(args) != 2:
        raise SystemExit('usage: compress.py [--decompress] INPUT OUTPUT')
    data = pathlib.Path(args[0]).read_bytes()
    pathlib.Path(args[1]).write_bytes(decompress(data) if decode else compress(data))


if __name__ == '__main__':
    main()

"""Size-only fitness; all repeated compression results must round-trip exactly."""
import pathlib
import subprocess
import sys
import time
import compress


def main():
    original = pathlib.Path('corpus.txt').read_bytes()
    start = time.monotonic()
    subprocess.run([sys.executable, 'compress.py', 'corpus.txt', 'out.bin'], check=True)
    subprocess.run([sys.executable, 'compress.py', '--decompress', 'out.bin', 'restored.txt'], check=True)
    packed = pathlib.Path('out.bin').read_bytes()
    if pathlib.Path('restored.txt').read_bytes() != original:
        return 0
    while True:
        candidate = compress.compress(original)
        if candidate != packed or compress.decompress(candidate) != original:
            return 0
        if time.monotonic() - start >= 0.4:
            break
    return max(0, 100 * (1 - len(packed) / len(original)))


if __name__ == '__main__':
    try:
        print(main())
    except Exception:
        print(0)

